LogicDefinition.ScriptText:
#load "reference"

/************************************************************************************
* Logic for safe signals from another station (pnpn-coupler or I-Device)
* Gaugler Frank
* Write: Receive safe signals
* V1.2.5: Gaugler - first edition
* V1.3.0: Gaugler - every station is different --> variable Inputs
* V1.4.0: Heußler - set up FEE HMI
* V1.5.0: Heußler - rework logic
************************************************************************************/

/*
+--------------------------------------------------------------------------------------------------------------------+
¦ Auszug: SIMATIC Safety - Projektieren und Programmieren Programmier- und Bedienhandbuch, 11/2023, A5E02714439-AN   ¦
+--------------------------------------------------------------------------------------------------------------------+

  Tabelle 10-1  Aufbau des relevanten Transferbereichs für Eingänge und des Simulationssteuerworts (Anweisung RCVDP)  
+----------+-----------------------------------+---------------------------------------------------------------+
¦ Byte     ¦ Bedeutung                         ¦ Bemerkung                                                     ¦
+----------+-----------------------------------+---------------------------------------------------------------¦
¦ 0        ¦ RD_BO_15 … RD_BO_08               ¦                                                               ¦
+----------+-----------------------------------+---------------------------------------------------------------¦
¦ 1        ¦ RD_BO_07 … RD_BO_00               ¦                                                               ¦
+----------+-----------------------------------+---------------------------------------------------------------¦
¦ 2        ¦ RD_I_00                           ¦ Word RD_I_00, MSB1) first                                     ¦
¦ 3        ¦                                   ¦                                                               ¦
+----------+-----------------------------------+---------------------------------------------------------------¦
¦ 4        ¦ RD_I_01                           ¦ Word RD_I_01, MSB1) first                                     ¦
¦ 5        ¦                                   ¦                                                               ¦
+----------+-----------------------------------+---------------------------------------------------------------¦
¦ 6        ¦ Simulationssteuerwort (High Byte) ¦ Bit 0…6: reserviert                                           ¦
¦          ¦                                   ¦ Bit 7: SIMULATION: Simulation RCVDP aktivieren                ¦
+----------+-----------------------------------+---------------------------------------------------------------¦
¦ 7        ¦ Simulationssteuerwort (Low Byte)  ¦ Bit 0: SEND_MODE: Ausgang SENDMODE setzen                     ¦
¦          ¦                                   ¦ Bit 1…7: reserviert                                           ¦
+----------+-----------------------------------+---------------------------------------------------------------¦
¦ 8 .. 11  ¦ reserviert                        ¦                                                               ¦
+----------+-----------------------------------+---------------------------------------------------------------+
  1) MSB: most significant bit                                                                                  


  Tabelle 10-2 Aufbau des relevanten Transferbereichs für Eingänge und des Simulationssteuerworts (Anweisung SENDDP)
+----------+-----------------------------------+---------------------------------------------------------------+
¦ Byte     ¦ Bedeutung                         ¦ Bemerkung                                                     ¦
+----------+-----------------------------------+---------------------------------------------------------------¦
¦ 0        ¦ Simulationssteuerwort (High Byte) ¦ Bit 0: STATUS_SUBS: Ausgang SUBS_ON setzen                    ¦
¦          ¦                                   ¦ Bit 1…6: reserviert                                           ¦
¦          ¦                                   ¦ Bit 7: SIMULATION: Simulation SENDDP aktivieren               ¦
+----------+-----------------------------------+---------------------------------------------------------------¦
¦ 1        ¦ Simulationssteuerwort (Low Byte)  ¦ Bit 0…7: reserviert                                           ¦
+----------+-----------------------------------+---------------------------------------------------------------¦
¦ 2 .. 5   ¦ reserviert                        ¦                                                               ¦
+----------+-----------------------------------+---------------------------------------------------------------+
*/


using System;
using System.Buffers.Binary;

// Get name of the element for HMI

HMI_LogicName = SceneObject.Name;

// Get PLC Outputs and copy to slots + HMI

//Byte 0
BitArray PLC_SEND_BYTE00_BitArray = new BitArray (new int[] {PLC_OUT_SEND_BYTE00});

HMI_Send_BO_00 = SIM_SD_BO_00 = PLC_SEND_BYTE00_BitArray[0];
HMI_Send_BO_01 = SIM_SD_BO_01 = PLC_SEND_BYTE00_BitArray[1];
HMI_Send_BO_02 = SIM_SD_BO_02 = PLC_SEND_BYTE00_BitArray[2];
HMI_Send_BO_03 = SIM_SD_BO_03 = PLC_SEND_BYTE00_BitArray[3];
HMI_Send_BO_04 = SIM_SD_BO_04 = PLC_SEND_BYTE00_BitArray[4];
HMI_Send_BO_05 = SIM_SD_BO_05 = PLC_SEND_BYTE00_BitArray[5];
HMI_Send_BO_06 = SIM_SD_BO_06 = PLC_SEND_BYTE00_BitArray[6];
HMI_Send_BO_07 = SIM_SD_BO_07 = PLC_SEND_BYTE00_BitArray[7];


//Byte 1
BitArray PLC_SEND_BYTE01_BitArray = new BitArray (new int[] {PLC_OUT_SEND_BYTE01});

HMI_Send_BO_08 = SIM_SD_BO_08 = PLC_SEND_BYTE01_BitArray[0];
HMI_Send_BO_09 = SIM_SD_BO_09 = PLC_SEND_BYTE01_BitArray[1];
HMI_Send_BO_10 = SIM_SD_BO_10 = PLC_SEND_BYTE01_BitArray[2];
HMI_Send_BO_11 = SIM_SD_BO_11 = PLC_SEND_BYTE01_BitArray[3];
HMI_Send_BO_12 = SIM_SD_BO_12 = PLC_SEND_BYTE01_BitArray[4];
HMI_Send_BO_13 = SIM_SD_BO_13 = PLC_SEND_BYTE01_BitArray[5];
HMI_Send_BO_14 = SIM_SD_BO_14 = PLC_SEND_BYTE01_BitArray[6];
HMI_Send_BO_15 = SIM_SD_BO_15 = PLC_SEND_BYTE01_BitArray[7];

// Int 1
byte[] ByteToInt01 = new byte[2] {PLC_OUT_SEND_BYTE03, PLC_OUT_SEND_BYTE02};
HMI_Send_I_00 = SIM_SD_I_00 = BitConverter.ToInt16(ByteToInt01);

// Int 2
byte[] ByteToInt02 = new byte[2] {PLC_OUT_SEND_BYTE05, PLC_OUT_SEND_BYTE04};
HMI_Send_I_01 = SIM_SD_I_01 = BitConverter.ToInt16(ByteToInt02);


// Set PLC Inputs

// Use HMI values
if(HMI_ReceiveValuesActive) {

    // Byte 0
    bool[] bitArrayByte0 = new bool [] {
    HMI_Receive_BO_00,
    HMI_Receive_BO_01,
    HMI_Receive_BO_02,
    HMI_Receive_BO_03,
    HMI_Receive_BO_04,
    HMI_Receive_BO_05,
    HMI_Receive_BO_06,
    HMI_Receive_BO_07,
    };

    BitArray bitsByte0 = new BitArray(bitArrayByte0);
    byte[] byteArrayByte0 = new byte[1];
    bitsByte0.CopyTo(byteArrayByte0, 0);

    PLC_IN_RECV_BYTE00 = byteArrayByte0[0];

    // Byte 1
    bool[] bitArrayByte1 = new bool [] {
    HMI_Receive_BO_08,
    HMI_Receive_BO_09,
    HMI_Receive_BO_10,
    HMI_Receive_BO_11,
    HMI_Receive_BO_12,
    HMI_Receive_BO_13,
    HMI_Receive_BO_14,
    HMI_Receive_BO_15,
    };

    BitArray bitsByte1 = new BitArray(bitArrayByte1);
    byte[] byteArrayByte1 = new byte[1];
    bitsByte1.CopyTo(byteArrayByte1, 0);

    PLC_IN_RECV_BYTE01 = byteArrayByte1[0];

    // Int 1
    byte[] byteHmiInt1 = BitConverter.GetBytes(HMI_Receive_I_00);
    PLC_IN_RECV_BYTE02 = byteHmiInt1[1];
    PLC_IN_RECV_BYTE03 = byteHmiInt1[0];

    // Int 2
    byte[] byteHmiInt2 = BitConverter.GetBytes(HMI_Receive_I_01);
    PLC_IN_RECV_BYTE02 = byteHmiInt2[1];
    PLC_IN_RECV_BYTE03 = byteHmiInt2[0];
}

// Use SIM values
else {


    // Byte 0
    bool[] bitArrayByte0 = new bool [] {
    SIM_RD_BO_00,
    SIM_RD_BO_01,
    SIM_RD_BO_02,
    SIM_RD_BO_03,
    SIM_RD_BO_04,
    SIM_RD_BO_05,
    SIM_RD_BO_06,
    SIM_RD_BO_07,
    };

    BitArray bitsByte0 = new BitArray(bitArrayByte0);
    byte[] byteArrayByte0 = new byte[1];
    bitsByte0.CopyTo(byteArrayByte0, 0);

    PLC_IN_RECV_BYTE00 = byteArrayByte0[0];


    // Byte 1
    bool[] bitArrayByte1 = new bool [] {
    SIM_RD_BO_08,
    SIM_RD_BO_09,
    SIM_RD_BO_10,
    SIM_RD_BO_11,
    SIM_RD_BO_12,
    SIM_RD_BO_13,
    SIM_RD_BO_14,
    SIM_RD_BO_15,
    };

    BitArray bitsByte1 = new BitArray(bitArrayByte1);
    byte[] byteArrayByte1 = new byte[1];
    bitsByte1.CopyTo(byteArrayByte1, 0);

    PLC_IN_RECV_BYTE01 = byteArrayByte1[0];

    // Int 1
    byte[] byteHmiInt1 = BitConverter.GetBytes(SIM_RD_I_00);
    PLC_IN_RECV_BYTE02 = byteHmiInt1[1];
    PLC_IN_RECV_BYTE03 = byteHmiInt1[0];
    // Int 2
    byte[] byteHmiInt2 = BitConverter.GetBytes(SIM_RD_I_01);
    PLC_IN_RECV_BYTE02 = byteHmiInt2[1];
    PLC_IN_RECV_BYTE03 = byteHmiInt2[0];



    // Display SIM values on HMI
    HMI_Receive_BO_00 = SIM_RD_BO_00;
    HMI_Receive_BO_01 = SIM_RD_BO_01;
    HMI_Receive_BO_02 = SIM_RD_BO_02;
    HMI_Receive_BO_03 = SIM_RD_BO_03;
    HMI_Receive_BO_04 = SIM_RD_BO_04;
    HMI_Receive_BO_05 = SIM_RD_BO_05;
    HMI_Receive_BO_06 = SIM_RD_BO_06;
    HMI_Receive_BO_07 = SIM_RD_BO_07;
    HMI_Receive_BO_08 = SIM_RD_BO_08;
    HMI_Receive_BO_09 = SIM_RD_BO_09;
    HMI_Receive_BO_10 = SIM_RD_BO_10;
    HMI_Receive_BO_11 = SIM_RD_BO_11;
    HMI_Receive_BO_12 = SIM_RD_BO_12;
    HMI_Receive_BO_13 = SIM_RD_BO_13;
    HMI_Receive_BO_14 = SIM_RD_BO_14;
    HMI_Receive_BO_15 = SIM_RD_BO_15;

    HMI_Receive_I_00 = SIM_RD_I_00;
    HMI_Receive_I_01 = SIM_RD_I_01;

}

// Set RCVDP & SENDDP to simulation mode
if (HMI_SimCouplerActive) {

    PLC_IN_RECV_BYTE06 = 128;
    PLC_IN_SEND_BYTE00 = 128;
}
else {
    PLC_IN_RECV_BYTE06 = 0;
    PLC_IN_SEND_BYTE00 = 0;
}
/*
// Handling CRC (only necessary for hardware in the loop)
// RECVDP
// Calculate

ushort crcRecvdp = ProfinetFunctions.CalculateCRCForRCVDP(new byte[8] {
PLC_IN_RECV_BYTE00,
PLC_IN_RECV_BYTE01,
PLC_IN_RECV_BYTE02,
PLC_IN_RECV_BYTE03,
PLC_IN_RECV_BYTE04,
PLC_IN_RECV_BYTE05,
PLC_IN_RECV_BYTE06,
PLC_IN_RECV_BYTE07},
HMI_RecvId);

// Write values to PLC
byte[] crcRecvdpBytes = BitConverter.GetBytes(crcRecvdp);
PLC_IN_RECV_BYTE10 = crcRecvdpBytes[0];
PLC_IN_RECV_BYTE11 = crcRecvdpBytes[1];


// SENDDP
// Calculate
ushort crcSenddp = ProfinetFunctions.CalculateCRCForRCVDP(new byte[2] {
PLC_IN_SEND_BYTE00,
PLC_IN_SEND_BYTE01},
HMI_SendId);

// Write values to PLC
byte[] crcSenddpBytes = BitConverter.GetBytes(crcSenddp);
PLC_OUT_SEND_BYTE04 = crcSenddpBytes[0];
PLC_OUT_SEND_BYTE05 = crcSenddpBytes[1];
*/
